function waypointmover(WPName: string, mode: string, speaker: Player)
	local wpchr = speaker.Character 
	if not wpchr then return false end
	local wproot = getRoot(wpchr)
	if not wproot then return false end
	local wphuman = wpchr:FindFirstChildOfClass('Humanoid')
	if not wphuman and (mode == "walkto" or mode == "pathfind") then return false end

	stopwpping(wphuman, wproot)
	local wpname_lc = tostring(WPName):lower()

	local function runPathfind(targetPos: Vector3, targetPart: BasePart?)
		task.wait()
		if wphuman.SeatPart then
			wphuman.Sit = false
			task.wait(.1)
		end

		local path = PathService:CreatePath()
		waypointwalkto = true

		task.spawn(function()
			while waypointwalkto and speaker.Character and wphuman.Parent and wproot.Parent do
				if targetPart then
					if not targetPart.Parent then break end
					targetPos = targetPart.Position
				end

				if (targetPos - wproot.Position).Magnitude <= 5 then
					break
				end

				local success = pcall(function()
					path:ComputeAsync(wproot.Position, targetPos)
				end)

				if success and path.Status == Enum.PathStatus.Success then
					local waypoints = path:GetWaypoints()
					for waypointIndex = 2, #waypoints do
						if not waypointwalkto or not wphuman.Parent or not wproot.Parent then break end
						local waypoint = waypoints[waypointIndex]
						if waypoint.Action == Enum.PathWaypointAction.Jump then
							wphuman.Jump = true
						end
						wphuman:MoveTo(waypoint.Position)

						local timeout = os.clock() + 3
						while waypointwalkto and wphuman.Parent and wproot.Parent and (waypoint.Position - wproot.Position).Magnitude > 5 and os.clock() < timeout do
							task.wait()
						end
					end
				else
					wphuman:MoveTo(targetPos)
					task.wait(0.25)
				end
				task.wait()
			end
			waypointwalkto = false
		end)
	end

	for i, _ in pairs(WayPoints) do
		if tostring(WayPoints[i].NAME):lower() == wpname_lc then
			local x = WayPoints[i].COORD[1]
			local y = WayPoints[i].COORD[2]
			local z = WayPoints[i].COORD[3]
			local TrueCoords = Vector3.new(x, y, z)

			if mode == "default" then
				wproot.CFrame = CFrame.new(TrueCoords)
			elseif mode == "tween" then
				WPactiveTween = TweenService:Create(wproot, TweenInfo.new(tweenSpeed, Enum.EasingStyle.Linear), {CFrame = CFrame.new(TrueCoords)})
				WPactiveTween:Play()
			elseif mode == "walkto" then
				if wphuman.SeatPart then
					wphuman.Sit = false
					task.wait(.1)
				end
				wphuman.WalkToPoint = TrueCoords
			elseif mode == "pathfind" then
				runPathfind(TrueCoords, nil)
			end
			return true
		end
	end

	for i, _ in pairs(pWayPoints) do
		if tostring(pWayPoints[i].NAME):lower() == wpname_lc then
			local pwppos = pWayPoints[i].COORD[1]
			if not pwppos or not pwppos.Parent then continue end

			if mode == "default" then
				wproot.CFrame = CFrame.new(pwppos.Position)
			elseif mode == "tween" then
				WPactiveTween = TweenService:Create(wproot, TweenInfo.new(tweenSpeed, Enum.EasingStyle.Linear), {CFrame = CFrame.new(pwppos.Position)})
				WPactiveTween:Play()
			elseif mode == "walkto" then
				if wphuman.SeatPart then
					wphuman.Sit = false
					task.wait(.1)
				end
				wphuman.WalkToPoint = pwppos.Position
			elseif mode == "pathfind" then
				runPathfind(pwppos.Position, pwppos)
			end
			return true
		end
	end

	return false
end

