-- line 7832: remove_waypoints (function)
function remove_waypoints(tbl, wpna: string, rmmode: boolean, shouldNotify: boolean)
	if not tbl then return end
	for i = #tbl, 1, -1 do
		local v = tbl[i]
		if rmmode then
			if v.GAME == PlaceId then
				table.remove(tbl, i)
			end
		elseif v.NAME:lower() == wpna then
			if not v.GAME or v.GAME == PlaceId then
				if shouldNotify then
					notify('Modified Waypoints', "Deleted waypoint: " .. v.NAME)
				end
				table.remove(tbl, i)
			end
		end
	end
end

