function wprm(wpna: string?, rmmode: boolean)
	local targetName = wpna and wpna:lower() or ""
	
	remove_waypoints(WayPoints, targetName, rmmode, not rmmode)
	remove_waypoints(AllWaypoints, targetName, rmmode, false)
	remove_waypoints(pWayPoints, targetName, rmmode, not rmmode)

	refreshwaypoints()
	updatesaves()
end

return {}
